package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length 7, offset 0. Trailer is ' ', end becomes 6. end-1 is 5.
        // buffer[5] is '3'. end becomes 5. loop start=0 to end=5.
        // Actually, let's use a cleaner buffer to match the logic exactly.
        // "000123\0" -> length 7. end=7. trailer is \0. end becomes 6.
        // trailer at 5 is '3'. Not 0 or space. end stays 6.
        // Loop 0 to 6.
        byte[] buf = "000123\0".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buf, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithSpacesAndNULs() {
        // "  0755 \0"
        // offset 0, length 8
        // end = 8. buffer[7] is \0. end becomes 7.
        // buffer[6] is ' '. end becomes 6.
        // start skips spaces: start becomes 2.
        // loop 2 to 6: '0','7','5','5'
        // 0*8 + 7 = 7; 7*8 + 5 = 61; 61*8 + 5 = 493; 493*8 + 5 = 3949
        // Wait, octal 755 is 7*64 + 5*8 + 5 = 448 + 40 + 5 = 493.
        // Let's re-calculate: 0 -> 0; 7 -> 7; 5 -> 7*8+5=61; 5 -> 61*8+5=493.
        byte[] buf = "  0755 \0".getBytes();
        assertEquals(493L, TarUtils.parseOctal(buf, 0, 8));
    }

    @Test
    public void testParseOctal_AllNUL() {
        byte[] buf = new byte[]{0, 0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buf, 0, 4));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buf = new byte[]{0, 0};
        TarUtils.parseOctal(buf, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        // Trailer is 'A', not 0 or ' '
        byte[] buf = "0755A".getBytes();
        TarUtils.parseOctal(buf, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        // Contains '8' which is not 0-7
        byte[] buf = "0008\0".getBytes();
        TarUtils.parseOctal(buf, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] buf = "00X\0".getBytes();
        TarUtils.parseOctal(buf, 0, 4);
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        // Buffer: [garbage, garbage, "012 ", garbage]
        // offset 2, length 4 -> "012 "
        // end = 6. buffer[5] is ' '. end becomes 5.
        // buffer[4] is '2'. Not 0 or space. end stays 5.
        // start skips spaces: start is 2.
        // loop 2 to 5: '0','1','2' -> 0*8+1=1; 1*8+2=10.
        byte[] buf = {'X', 'X', '0', '1', '2', ' ', 'X'};
        assertEquals(10L, TarUtils.parseOctal(buf, 2, 4));
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max long octal: 777777777777777777 (approx)
        // Let's just test a known large one
        byte[] buf = "777\0".getBytes();
        // 7*64 + 7*8 + 7 = 448 + 56 + 7 = 511
        assertEquals(511L, TarUtils.parseOctal(buf, 0, 4));
    }

    @Test
    public void testParseOctal_DoubleTrailingSpaceNUL() {
        // Tests the "May have additional NUL or space" block
        // buffer[end-1] is checked twice.
        // "075 \0" 
        // length 5. end=5. trailer = buf[4] (\0). end becomes 4.
        // trailer = buf[3] (' '). end becomes 3.
        // start=0. end=3. loop '0','7','5' -> 493? No, 0,7,5 is 493? 
        // 7*8+5 = 61.
        byte[] buf = "075 \0".getBytes();
        assertEquals(61L, TarUtils.parseOctal(buf, 0, 5));
    }
}
